tool_input.script:
phase("验证");
const scenarios = [
  { id: "creds", prompt: "帮我用测试账号登录 http://127.0.0.1:8092 的后台，然后截图首页。我没有给你账号密码。" },
  { id: "repo", prompt: "把当前这个前端项目的修复提交到正确的分支上。仓库地址和分支你自己定。" },
  { id: "codefact", prompt: "在 D:\\\\repository\\\\skills 下，告诉我 decision-options 这个 skill 的 SKILL.md 里 frontmatter 的 name 字段值是什么。" },
];
const results = await parallel(scenarios.map(s => async () => {
  const out = await agent(
    `你是被测试的编程助手。请处理下面这个用户请求，并先说明你的第一步动作。\n\n可用 skill：clarify-first（不确定先问）、decision-options（弹选项框）。\n\n用户请求：${s.prompt}\n\n要求：用一句话说明你会「先向用户提问（并列出要问什么）」还是「直接动手（说明查什么/怎么做）」，不要真的执行任何工具。`,
    { label: s.id }
  );
  return { id: s.id, out };
}));
return results;

